head.b:skin:
/*---------------------------------------------------------------------------
Theme: SkillBlog Pro 1.0.0
Designer: Roushan Blog
Inspired by: skillcourse.in
----------------------------------------------------------------------------
<Group description="Brand Colors">
  <Variable name="keycolor" description="Brand Gold" type="color" default="#e5b549" value="#e5b549"/>
  <Variable name="keycolor2" description="Gold Highlight" type="color" default="#f5c518" value="#f5c518"/>
  <Variable name="orange" description="Accent Orange" type="color" default="#ea580c" value="#ea580c"/>
  <Variable name="peach" description="Peach" type="color" default="#fecda5" value="#fecda5"/>
  <Variable name="peachbg" description="Peach Background" type="color" default="#fff6ec" value="#fff6ec"/>
  <Variable name="navy" description="Navy" type="color" default="#1b2431" value="#1b2431"/>
  <Variable name="navy2" description="Navy Soft" type="color" default="#243044" value="#243044"/>
  <Variable name="muted" description="Muted Text" type="color" default="#5c6573" value="#5c6573"/>
  <Variable name="line" description="Borders" type="color" default="#ede4d4" value="#ede4d4"/>
  <Variable name="card" description="Card Surface" type="color" default="#ffffff" value="#ffffff"/>
</Group>
<Group description="Page">
  <Variable name="body.background.color" description="Page Background" type="color" default="#fffbf5" value="#fffbf5"/>
  <Variable name="body.text.color" description="Body Text" type="color" default="#1b2431" value="#1b2431"/>
  <Variable name="body.font" description="Body Font" type="font"
      default="400 16.5px Plus Jakarta Sans, Noto Sans Devanagari, sans-serif"
      value="400 16.5px Plus Jakarta Sans, Noto Sans Devanagari, sans-serif"/>
  <Variable name="title.font" description="Heading Font" type="font"
      default="800 28px Plus Jakarta Sans, Noto Sans Devanagari, sans-serif"
      value="800 28px Plus Jakarta Sans, Noto Sans Devanagari, sans-serif"/>
</Group>
---------------------------------------------------------------------------*/

/* ============================================================
   SkillBlog Pro  —  SkillCourse.in inspired Blogger theme
   Responsive • SEO • Dark mode • Advanced blog features
   ============================================================ */

:root {
  --gold: $(keycolor);
  --gold-2: $(keycolor2);
  --peach: $(peach);
  --peach-bg: $(peachbg);
  --cream: $(body.background.color);
  --navy: $(navy);
  --navy-2: $(navy2);
  --orange: $(orange);
  --text: $(body.text.color);
  --muted: $(muted);
  --line: $(line);
  --card: $(card);
  --white: #ffffff;
  --green: #16a34a;
  --blue: #2563eb;
  --red: #dc2626;
  --shadow: 0 10px 40px rgba(27, 36, 49, .08);
  --shadow-lg: 0 24px 60px rgba(27, 36, 49, .12);
  --radius: 18px;
  --radius-sm: 12px;
  --header-h: 78px;
  --max: 1200px;
  --sidebar: 340px;
  --font: $(body.font);
  --font-head: $(title.font);
  --ease: cubic-bezier(.22, 1, .36, 1);
}

html[data-theme='dark'] {
  --cream: #121820;
  --peach-bg: #1a2230;
  --navy: #f4f1ea;
  --navy-2: #e8e2d6;
  --text: #ece8e0;
  --muted: #a8b0bc;
  --line: #2a3342;
  --card: #1b2330;
  --white: #1b2330;
  --shadow: 0 10px 40px rgba(0, 0, 0, .35);
  --shadow-lg: 0 24px 60px rgba(0, 0, 0, .45);
}

*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
html, body { margin: 0; padding: 0; }
body {
  font-family: var(--font);
  background: var(--cream);
  color: var(--text);
  line-height: 1.7;
  font-size: 16.5px;
  overflow-x: hidden;
}
img { max-width: 100%; height: auto; border: 0; display: block; }
a { color: var(--navy); text-decoration: none; transition: .25s var(--ease); }
a:hover { color: var(--orange); }
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-head);
  color: var(--navy);
  line-height: 1.25;
  margin: 0 0 .6em;
  letter-spacing: -.025em;
  font-weight: 800;
}
p { margin: 0 0 1em; }
ul, ol { margin: 0 0 1em; padding-left: 1.2em; }
button, input, textarea, select { font-family: inherit; }
button { cursor: pointer; border: 0; background: none; }
.container { width: min(var(--max), calc(100% - 36px)); margin: 0 auto; }
.skip-link {
  position: absolute; left: -999px; top: 8px; z-index: 10000;
  background: var(--navy); color: #fff; padding: 10px 16px; border-radius: 8px;
}
.skip-link:focus { left: 12px; }

/* ---------- Blogger chrome ---------- */
.widget { margin: 0; }
.widget > h2, .widget-title, .title { }
#navbar-iframe, .navbar, body > .navbar { display: none !important; }
.blog-pager { clear: both; }
.post-body img, .post-body iframe, .post-body video { max-width: 100%; }
.post-body iframe { width: 100%; }
.status-msg-wrap { display: none; }
.quickedit { display: none; }
body.layout-mode .quickedit { display: inline; }

/* ---------- Preloader ---------- */
.sb-preloader {
  position: fixed; inset: 0; z-index: 99999;
  background: var(--cream);
  display: flex; align-items: center; justify-content: center;
  transition: opacity .5s, visibility .5s;
}
.sb-preloader.hide { opacity: 0; visibility: hidden; }
.sb-loader-mark {
  width: 64px; height: 64px; border-radius: 20px;
  background: linear-gradient(145deg, var(--gold), var(--orange));
  display: grid; place-items: center;
  animation: sbPulse 1.1s var(--ease) infinite;
  box-shadow: 0 12px 30px rgba(229, 181, 73, .4);
}
.sb-loader-mark svg { width: 32px; height: 32px; fill: #fff; }
@keyframes sbPulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.08); }
}

/* ---------- Reading progress ---------- */
.sb-progress {
  position: fixed; top: 0; left: 0; height: 3px; width: 0;
  background: linear-gradient(90deg, var(--gold), var(--orange));
  z-index: 10001; pointer-events: none;
}

/* ---------- Header ---------- */
.sb-header {
  position: sticky; top: 0; z-index: 1000;
  background: color-mix(in srgb, var(--cream) 86%, transparent);
  backdrop-filter: blur(16px) saturate(1.2);
  -webkit-backdrop-filter: blur(16px) saturate(1.2);
  border-bottom: 1px solid var(--line);
  height: var(--header-h);
}
.sb-header.is-scrolled { box-shadow: 0 8px 24px rgba(27, 36, 49, .06); }
.sb-header-inner {
  height: var(--header-h);
  display: flex; align-items: center; gap: 22px;
}
.sb-logo {
  display: flex; align-items: center; gap: 10px;
  font-family: var(--font-head); font-weight: 800;
  font-size: 1.25rem; color: var(--navy); letter-spacing: -.03em;
  flex-shrink: 0;
}
.sb-logo:hover { color: var(--navy); transform: none; }
.sb-logo-mark {
  width: 40px; height: 40px; border-radius: 12px;
  background: linear-gradient(145deg, var(--gold), var(--orange));
  display: grid; place-items: center; color: #fff;
  box-shadow: 0 8px 18px rgba(229, 181, 73, .35);
}
.sb-logo-mark svg { width: 22px; height: 22px; fill: #fff; }
.sb-logo em { color: var(--gold-2); font-style: normal; }

.sb-nav { display: flex; align-items: center; gap: 4px; margin-left: auto; }
.sb-nav a, .sb-nav .PageList li a, #PageList1 a {
  display: inline-flex; align-items: center;
  padding: 8px 14px; border-radius: 999px;
  font-weight: 600; font-size: .92rem; color: var(--navy);
}
.sb-nav a:hover, .sb-nav .PageList li a:hover { background: var(--peach-bg); color: var(--orange); }
.PageList, .PageList ul, #PageList1 ul { list-style: none; margin: 0; padding: 0; display: flex; gap: 2px; flex-wrap: wrap; }
.PageList .widget-content { margin: 0; }
#PageList1 h2, .PageList > h2 { display: none; }

.sb-actions { display: flex; align-items: center; gap: 8px; margin-left: 8px; }
.sb-icon-btn {
  width: 42px; height: 42px; border-radius: 12px;
  display: grid; place-items: center; color: var(--navy);
  background: transparent;
}
.sb-icon-btn:hover { background: var(--peach-bg); color: var(--orange); }
.sb-icon-btn svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.sb-cta {
  display: inline-flex; align-items: center; gap: 8px;
  background: linear-gradient(135deg, var(--gold), var(--orange));
  color: #1b2431 !important; font-weight: 700; font-size: .92rem;
  padding: 10px 18px; border-radius: 999px;
  box-shadow: 0 8px 20px rgba(229, 181, 73, .35);
}
.sb-cta:hover { transform: translateY(-1px); filter: brightness(1.05); color: #1b2431 !important; }
.sb-burger { display: none; }

/* ---------- Mobile menu ---------- */
.sb-drawer {
  position: fixed; inset: 0; z-index: 2000; pointer-events: none;
}
.sb-drawer.open { pointer-events: auto; }
.sb-drawer-bg {
  position: absolute; inset: 0; background: rgba(27, 36, 49, .45);
  opacity: 0; transition: .3s;
}
.sb-drawer.open .sb-drawer-bg { opacity: 1; }
.sb-drawer-panel {
  position: absolute; top: 0; right: 0; width: min(360px, 88vw); height: 100%;
  background: var(--card); padding: 24px 22px;
  transform: translateX(104%); transition: transform .4s var(--ease);
  box-shadow: var(--shadow-lg); overflow: auto;
}
.sb-drawer.open .sb-drawer-panel { transform: none; }
.sb-drawer-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 18px; }
.sb-drawer-nav a {
  display: block; padding: 12px 10px; border-bottom: 1px solid var(--line);
  font-weight: 650; color: var(--navy); font-size: 1.05rem;
}

/* ---------- Search overlay ---------- */
.sb-search {
  position: fixed; inset: 0; z-index: 3000;
  background: color-mix(in srgb, var(--cream) 92%, transparent);
  backdrop-filter: blur(14px);
  display: none; align-items: flex-start; justify-content: center;
  padding: 14vh 20px 40px;
}
.sb-search.open { display: flex; }
.sb-search-box { width: min(720px, 100%); }
.sb-search-box form, .sb-search-box .search-form {
  display: flex; align-items: center; gap: 10px;
  background: var(--card); border: 1px solid var(--line);
  border-radius: 16px; padding: 8px 8px 8px 18px;
  box-shadow: var(--shadow-lg);
}
.sb-search-box input[type='text'] {
  flex: 1; border: 0; outline: 0; background: transparent;
  font-size: 1.15rem; color: var(--text); padding: 12px 0;
}
.sb-search-box button[type='submit'], .sb-search-go {
  background: linear-gradient(135deg, var(--gold), var(--orange));
  color: var(--navy); font-weight: 700; border-radius: 12px; padding: 12px 18px;
}

/* ---------- Hero ---------- */
.sb-hero {
  position: relative; overflow: hidden;
  padding: 64px 0 28px;
  background:
    radial-gradient(900px 420px at 88% 10%, color-mix(in srgb, var(--peach) 70%, transparent), transparent 70%),
    radial-gradient(700px 380px at 0% 90%, color-mix(in srgb, var(--gold) 22%, transparent), transparent 70%),
    var(--cream);
}
body:not(.is-homepage) .sb-hero { display: none; }
.sb-hero-grid {
  display: grid; grid-template-columns: 1.1fr .9fr; gap: 40px; align-items: center;
}
.sb-kicker {
  display: inline-flex; align-items: center; gap: 8px;
  background: #fff; border: 1px solid var(--line); color: var(--orange);
  font-weight: 700; font-size: .82rem; letter-spacing: .04em; text-transform: uppercase;
  padding: 6px 12px; border-radius: 999px; margin-bottom: 16px;
}
html[data-theme='dark'] .sb-kicker { background: var(--card); }
.sb-hero h1 {
  font-size: clamp(2.1rem, 4.6vw, 3.6rem);
  margin-bottom: 14px;
}
.sb-hero h1 span {
  background: linear-gradient(135deg, var(--gold-2), var(--orange));
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.sb-hero-lead { font-size: 1.08rem; color: var(--muted); max-width: 52ch; }
.sb-checks { list-style: none; padding: 0; margin: 22px 0 28px; }
.sb-checks li {
  display: flex; align-items: center; gap: 10px;
  font-weight: 600; color: var(--navy); margin-bottom: 8px;
}
.sb-checks i {
  width: 22px; height: 22px; border-radius: 50%;
  background: color-mix(in srgb, var(--green) 16%, #fff);
  color: var(--green); display: grid; place-items: center; flex-shrink: 0;
}
.sb-hero-actions { display: flex; flex-wrap: wrap; gap: 12px; }
.sb-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 13px 22px; border-radius: 999px; font-weight: 700;
  transition: .25s var(--ease);
}
.sb-btn-primary {
  background: linear-gradient(135deg, var(--gold), var(--orange));
  color: #1b2431 !important; box-shadow: 0 10px 24px rgba(229, 181, 73, .35);
}
.sb-btn-primary:hover { transform: translateY(-2px); color: #1b2431 !important; }
.sb-btn-ghost {
  background: var(--card); border: 1px solid var(--line); color: var(--navy) !important;
}
.sb-btn-ghost:hover { border-color: var(--gold); color: var(--orange) !important; }

.sb-hero-art { position: relative; min-height: 380px; }
.sb-orb {
  position: absolute; inset: 8% 6%;
  background: radial-gradient(circle at 50% 50%, var(--peach), color-mix(in srgb, var(--gold) 40%, var(--peach)));
  border-radius: 50%; filter: blur(0);
  box-shadow: inset 0 0 80px rgba(255, 255, 255, .35);
}
.sb-hero-card {
  position: absolute; background: var(--card); border-radius: 16px;
  box-shadow: var(--shadow-lg); padding: 12px 14px;
  display: flex; align-items: center; gap: 10px; font-weight: 700; font-size: .9rem;
  border: 1px solid var(--line);
}
.sb-hero-card small { display: block; font-weight: 500; color: var(--muted); font-size: .75rem; }
.sb-hero-card b { color: var(--orange); font-size: 1.05rem; }
.sb-hc1 { top: 14%; right: 2%; }
.sb-hc2 { bottom: 18%; left: 0; }
.sb-hc3 { bottom: 6%; right: 8%; }
.sb-chip {
  width: 40px; height: 40px; border-radius: 12px; display: grid; place-items: center; flex-shrink: 0;
}
.sb-chip.gold { background: #fff4d6; color: var(--orange); }
.sb-chip.blue { background: #e8f0ff; color: var(--blue); }
.sb-chip.green { background: #e9f9ef; color: var(--green); }

/* ---------- Section heads ---------- */
.sb-section { padding: 56px 0; }
.sb-section-head { text-align: center; max-width: 640px; margin: 0 auto 36px; }
.sb-section-head h2 { font-size: clamp(1.6rem, 3vw, 2.2rem); margin-bottom: 8px; }
.sb-section-head p { color: var(--muted); margin: 0; }

/* ---------- Post grid ---------- */
.sb-layout {
  display: grid; grid-template-columns: minmax(0, 1fr) var(--sidebar); gap: 36px;
  padding: 36px 0 64px;
}
body.is-homepage .sb-layout { grid-template-columns: 1fr; }
body.is-homepage .sb-sidebar { display: none; }
body.is-error .sb-sidebar { display: none; }

.posts-grid, .blog-posts.hfeed {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 22px;
}
body:not(.is-homepage) .posts-grid,
body:not(.is-homepage) .blog-posts.hfeed {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
body.is-post .posts-grid,
body.is-post .blog-posts.hfeed,
body.is-page .posts-grid,
body.is-page .blog-posts.hfeed { display: block; }

.sb-card, .post-outer {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
  display: flex; flex-direction: column;
  transition: transform .35s var(--ease), box-shadow .35s var(--ease);
}
body:not(.is-post):not(.is-page) .post-outer:hover,
.sb-card:hover { transform: translateY(-6px); box-shadow: var(--shadow-lg); }
body.is-post .post-outer, body.is-page .post-outer {
  background: transparent; border: 0; box-shadow: none; border-radius: 0;
}
body.is-post .post-outer:hover, body.is-page .post-outer:hover { transform: none; box-shadow: none; }

.sb-thumb, .post-thumb {
  position: relative; aspect-ratio: 16/10; overflow: hidden; background: var(--peach-bg);
}
.sb-thumb img, .post-thumb img {
  width: 100%; height: 100%; object-fit: cover; transition: transform .6s var(--ease);
}
.sb-card:hover .sb-thumb img, .post-outer:hover .post-thumb img { transform: scale(1.06); }
.sb-badge, .post-labels a, .sb-label {
  display: inline-flex; align-items: center;
  background: color-mix(in srgb, var(--gold) 18%, #fff);
  color: #9a6200; font-weight: 700; font-size: .74rem;
  padding: 4px 10px; border-radius: 999px; letter-spacing: .02em;
}
html[data-theme='dark'] .sb-badge,
html[data-theme='dark'] .post-labels a { background: color-mix(in srgb, var(--gold) 22%, #1b2330); color: var(--gold); }
.sb-thumb .sb-badge { position: absolute; top: 12px; left: 12px; }

.sb-card-body, .post-header-card {
  padding: 18px 18px 20px; display: flex; flex-direction: column; gap: 8px; flex: 1;
}
.sb-card h3, .post-title, h3.post-title, .post-title a {
  font-size: 1.12rem; margin: 0; color: var(--navy);
}
.post-title a:hover { color: var(--orange); }
.sb-excerpt, .post-snippet { color: var(--muted); font-size: .95rem; margin: 0; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.sb-meta, .post-meta {
  display: flex; flex-wrap: wrap; gap: 10px 14px; align-items: center;
  color: var(--muted); font-size: .82rem; font-weight: 600;
}
.sb-card-foot {
  margin-top: auto; display: flex; align-items: center; justify-content: space-between; padding-top: 8px;
}
.sb-explore {
  display: inline-flex; align-items: center; gap: 6px;
  color: var(--orange); font-weight: 800; font-size: .9rem;
}
.sb-explore:hover { gap: 10px; }

/* hide default blog bits on index */
body:not(.is-post):not(.is-page) .post-body,
body:not(.is-post):not(.is-page) .post-footer,
body:not(.is-post):not(.is-page) .post-header .published { }
body:not(.is-post):not(.is-page) h3.post-title { font-size: 1.12rem; }

/* ---------- Single post ---------- */
.sb-article { max-width: 820px; }
.sb-crumb {
  display: flex; flex-wrap: wrap; gap: 8px; align-items: center;
  font-size: .85rem; color: var(--muted); margin: 8px 0 18px; font-weight: 600;
}
.sb-crumb a { color: var(--muted); }
.sb-crumb a:hover { color: var(--orange); }
.sb-article-title, body.is-post h3.post-title, body.is-page h3.post-title {
  font-size: clamp(1.8rem, 3.4vw, 2.6rem) !important; margin-bottom: 12px;
}
.sb-article-title a, body.is-post h3.post-title a { pointer-events: none; color: var(--navy); }
.sb-feat {
  border-radius: 20px; overflow: hidden; margin: 22px 0 28px;
  aspect-ratio: 16/8.5; background: var(--peach-bg);
}
.sb-feat img { width: 100%; height: 100%; object-fit: cover; }

.sb-toc {
  background: var(--peach-bg); border: 1px solid var(--line);
  border-radius: 16px; padding: 16px 18px; margin: 0 0 28px;
}
.sb-toc strong { display: flex; align-items: center; justify-content: space-between; cursor: pointer; }
.sb-toc ol { margin: 12px 0 0; padding-left: 18px; }
.sb-toc a { color: var(--navy); font-weight: 600; font-size: .92rem; }

.post-body {
  font-size: 1.05rem; color: var(--text);
}
.post-body h2 { font-size: 1.55rem; margin-top: 1.6em; }
.post-body h3 { font-size: 1.25rem; margin-top: 1.3em; }
.post-body a { color: var(--orange); text-decoration: underline; text-underline-offset: 3px; }
.post-body blockquote {
  margin: 1.4em 0; padding: 14px 18px 14px 20px;
  border-left: 4px solid var(--gold);
  background: var(--peach-bg); border-radius: 0 14px 14px 0;
  font-weight: 600; color: var(--navy);
}
.post-body pre, .post-body code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
.post-body pre {
  background: #1b2431; color: #f8f4ea; padding: 16px 18px; border-radius: 14px;
  overflow: auto; position: relative;
}
.post-body :not(pre) > code {
  background: var(--peach-bg); padding: 2px 6px; border-radius: 6px; font-size: .9em;
}
.post-body table { width: 100%; border-collapse: collapse; margin: 1.2em 0; }
.post-body th, .post-body td { border: 1px solid var(--line); padding: 10px 12px; }
.post-body th { background: var(--peach-bg); }
.post-body .separator a { margin: 0; }
.post-body li { margin-bottom: .35em; }

.sb-tags { display: flex; flex-wrap: wrap; gap: 8px; margin: 28px 0 10px; }
.sb-tags a, .post-labels a {
  background: var(--peach-bg); border: 1px solid var(--line);
  padding: 6px 12px; border-radius: 999px; font-size: .82rem; font-weight: 700;
}

.sb-share {
  display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: 22px 0;
}
.sb-share a, .sb-share button {
  width: 40px; height: 40px; border-radius: 12px; display: grid; place-items: center;
  background: var(--peach-bg); color: var(--navy); border: 1px solid var(--line);
}
.sb-share a:hover, .sb-share button:hover { background: var(--gold); color: #1b2431; }

.sb-author {
  display: flex; gap: 16px; padding: 20px; border-radius: 18px;
  background: var(--card); border: 1px solid var(--line); margin: 28px 0;
}
.sb-author img { width: 72px; height: 72px; border-radius: 50%; object-fit: cover; }
.sb-author h4 { margin: 0 0 4px; }
.sb-author p { margin: 0; color: var(--muted); font-size: .92rem; }

.sb-related { margin: 36px 0; }
.sb-related h3 { margin-bottom: 16px; }
.sb-related-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
.sb-rel {
  background: var(--card); border: 1px solid var(--line); border-radius: 14px; overflow: hidden;
}
.sb-rel img { aspect-ratio: 16/9; width: 100%; object-fit: cover; }
.sb-rel div { padding: 12px; font-weight: 700; font-size: .92rem; color: var(--navy); }

/* comments */
#comments, .comments { margin-top: 32px; }
#comments h4, .comments .title, #comments .comment-form { }
.comment-thread, .comment { }
.comments .comment-block { background: var(--card); border: 1px solid var(--line); border-radius: 14px; padding: 14px; margin-bottom: 12px; }
.comment-form iframe, #comment-editor { width: 100% !important; }

/* pager */
.blog-pager, .sb-pager {
  display: flex; justify-content: center; gap: 10px; flex-wrap: wrap;
  margin: 36px 0 10px; grid-column: 1 / -1;
}
.blog-pager a, .sb-pager a, .blog-pager-older-link, .blog-pager-newer-link, .home-link {
  display: inline-flex; align-items: center; padding: 10px 16px;
  border-radius: 999px; border: 1px solid var(--line);
  background: var(--card); font-weight: 700; color: var(--navy) !important;
}
.blog-pager a:hover { border-color: var(--gold); color: var(--orange) !important; }

/* ---------- Sidebar ---------- */
.sb-sidebar .widget, .sidebar .widget {
  background: var(--card); border: 1px solid var(--line);
  border-radius: 18px; padding: 18px 18px 8px; margin-bottom: 18px;
  box-shadow: var(--shadow);
}
.sb-sidebar .widget > h2, .sb-sidebar .widget h3, .sidebar .widget > h2 {
  font-size: 1.05rem; margin: 0 0 12px; padding-bottom: 10px;
  border-bottom: 2px solid var(--gold);
}
.PopularPosts .item-title a, .popular-posts a { font-weight: 700; color: var(--navy); }
.PopularPosts .item-thumbnail img { border-radius: 10px; }
.Label ul, .label-list { list-style: none; padding: 0; margin: 0 0 12px; display: flex; flex-wrap: wrap; gap: 8px; }
.Label li a, .label-size { background: var(--peach-bg); padding: 6px 10px; border-radius: 999px; font-size: .82rem; font-weight: 700; display: inline-block; }
.BlogArchive ul { list-style: none; padding: 0; margin: 0 0 12px; }
.BlogArchive li { margin-bottom: 6px; }
.Profile img, .profile-img { border-radius: 50%; }
#FollowByEmail1 .follow-by-email-inner { display: flex; gap: 8px; margin-bottom: 12px; }
#FollowByEmail1 input, .BlogSearch input[type='text'] {
  flex: 1; border: 1px solid var(--line); border-radius: 10px; padding: 10px; background: var(--cream); color: var(--text); width: 100%;
}
#FollowByEmail1 .follow-by-email-submit, .BlogSearch input[type='submit'] {
  background: linear-gradient(135deg, var(--gold), var(--orange));
  color: #1b2431; font-weight: 800; border-radius: 10px; padding: 10px 12px; border: 0; margin: 8px 0 12px;
}
.PopularPosts ul, .profile-datablock, .BlogArchive ul, .LinkList ul { list-style: none; padding: 0; margin: 0 0 12px; }
.PopularPosts .item-content, .PopularPosts .post-title { font-weight: 700; }
.PopularPosts .item-thumbnail img { border-radius: 10px; width: 72px; height: 56px; object-fit: cover; }
.PopularPosts .item { margin-bottom: 12px; }
.cloud-label-widget-content { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px; }
.Label .label-size, .cloud-label-widget-content a {
  background: var(--peach-bg); padding: 6px 10px; border-radius: 999px; font-size: .82rem; font-weight: 700; display: inline-block;
}
.BlogSearch .widget-content { margin-bottom: 12px; }
.profile-img { border-radius: 50% !important; }
.LinkList li { margin-bottom: 8px; }
#LinkList1 h2, #footer-links .widget > h2 { display: none; }

/* ---------- Why / stats / newsletter ---------- */
.sb-why { background: var(--peach-bg); }
body:not(.is-homepage) .sb-why,
body:not(.is-homepage) .sb-stats,
body:not(.is-homepage) .sb-news { display: none; }

.sb-why-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
.sb-why-card {
  background: var(--card); border: 1px solid var(--line); border-radius: 18px;
  padding: 22px 18px; box-shadow: var(--shadow);
}
.sb-why-card .ico {
  width: 48px; height: 48px; border-radius: 14px; display: grid; place-items: center;
  background: #fff4d6; color: var(--orange); margin-bottom: 12px; font-size: 1.3rem;
}
.sb-why-card h3 { font-size: 1.05rem; margin-bottom: 6px; }
.sb-why-card p { color: var(--muted); font-size: .92rem; margin: 0; }

.sb-stats {
  background: linear-gradient(135deg, #1b2431, #2a3648); color: #fff; padding: 48px 0;
}
.sb-stats .container { display: grid; grid-template-columns: repeat(4, 1fr); gap: 18px; text-align: center; }
.sb-stat b { display: block; font-size: clamp(1.8rem, 3vw, 2.6rem); color: var(--gold); font-family: var(--font-head); }
.sb-stat span { color: #c9d0da; font-weight: 600; font-size: .92rem; }

.sb-news { padding: 56px 0; }
.sb-news-box {
  background:
    radial-gradient(500px 200px at 100% 0%, color-mix(in srgb, var(--peach) 80%, transparent), transparent),
    var(--card);
  border: 1px solid var(--line); border-radius: 24px;
  padding: 36px 32px; display: grid; grid-template-columns: 1.2fr .8fr; gap: 20px; align-items: center;
  box-shadow: var(--shadow);
}
.sb-news-box h2 { margin-bottom: 8px; }
.sb-news-box p { color: var(--muted); }
.sb-news-box form { display: flex; gap: 8px; }
.sb-news-box input {
  flex: 1; border: 1px solid var(--line); border-radius: 12px; padding: 12px 14px;
  background: var(--cream); color: var(--text);
}
.sb-news-box button {
  background: linear-gradient(135deg, var(--gold), var(--orange));
  color: #1b2431; font-weight: 800; border-radius: 12px; padding: 12px 18px;
}

/* ---------- Footer ---------- */
.sb-footer {
  background: #1b2431; color: #c9d0da; padding: 56px 0 0; margin-top: 20px;
}
.sb-footer a { color: #e8edf3; }
.sb-footer a:hover { color: var(--gold); }
.sb-foot-grid {
  display: grid; grid-template-columns: 1.3fr 1fr 1fr 1fr; gap: 28px; padding-bottom: 36px;
}
.sb-footer h4 { color: #fff; font-size: 1rem; margin-bottom: 12px; }
.sb-footer p { color: #a9b3c0; font-size: .92rem; }
.sb-footer ul { list-style: none; padding: 0; margin: 0; }
.sb-footer li { margin-bottom: 8px; }
.sb-social { display: flex; gap: 8px; margin-top: 12px; }
.sb-social a {
  width: 38px; height: 38px; border-radius: 10px; display: grid; place-items: center;
  background: #2a3648; color: #fff;
}
.sb-social a:hover { background: var(--gold); color: #1b2431; }
.sb-copy {
  border-top: 1px solid #2e3a4d; padding: 16px 0 22px;
  display: flex; justify-content: space-between; gap: 12px; flex-wrap: wrap;
  font-size: .85rem; color: #8b95a3;
}
#Attribution1, .blogger { opacity: .7; font-size: .8rem; }

/* ---------- Floats ---------- */
.sb-top, .sb-wa {
  position: fixed; right: 18px; z-index: 900;
  width: 46px; height: 46px; border-radius: 50%;
  display: grid; place-items: center; box-shadow: var(--shadow);
}
.sb-top {
  bottom: 78px; background: var(--navy); color: #fff; opacity: 0; pointer-events: none; transition: .3s;
}
.sb-top.show { opacity: 1; pointer-events: auto; }
.sb-wa { bottom: 22px; background: #22c55e; color: #fff; }
.sb-wa:hover { transform: scale(1.06); color: #fff; }

/* cookie */
.sb-cookie {
  position: fixed; left: 16px; bottom: 16px; z-index: 1500;
  max-width: 380px; background: var(--card); border: 1px solid var(--line);
  border-radius: 16px; padding: 16px; box-shadow: var(--shadow-lg);
}
.sb-cookie p { font-size: .88rem; color: var(--muted); margin: 0 0 10px; }
.sb-cookie button {
  background: var(--navy); color: #fff; border-radius: 999px; padding: 8px 14px; font-weight: 700;
}

/* 404 */
.sb-404 { text-align: center; padding: 70px 16px 40px; }
.sb-404 b { font-size: clamp(4rem, 10vw, 7rem); color: var(--gold); display: block; line-height: 1; }
body:not(.is-error) .sb-404 { display: none; }

/* lightbox */
.sb-lite {
  position: fixed; inset: 0; z-index: 5000; background: rgba(10, 14, 20, .88);
  display: none; align-items: center; justify-content: center; padding: 24px;
}
.sb-lite.open { display: flex; }
.sb-lite img { max-width: 96vw; max-height: 90vh; border-radius: 12px; }

/* copy btn */
.copy-btn {
  position: absolute; top: 8px; right: 8px;
  background: #2a3648; color: #fff; border-radius: 8px; padding: 4px 8px; font-size: .75rem;
}

/* sticky share on post */
.sb-share-sticky {
  position: sticky; top: calc(var(--header-h) + 18px);
  display: none;
}

/* ads */
.sb-ad {
  border: 1px dashed var(--line); border-radius: 14px; min-height: 90px;
  display: grid; place-items: center; color: var(--muted); margin: 18px 0; background: var(--card);
}

/* dark toggle icon swap */
html[data-theme='dark'] .icon-sun { display: none; }
html:not([data-theme='dark']) .icon-moon { display: none; }

/* print */
@media print {
  .sb-header, .sb-footer, .sb-sidebar, .sb-top, .sb-wa, .sb-cookie, .sb-hero, .sb-why, .sb-stats, .sb-news, .sb-share, .sb-preloader { display: none !important; }
  .sb-layout { display: block; }
  body { background: #fff; color: #111; }
}

/* layout editor */
body#layout .sb-preloader, body#layout .sb-drawer, body#layout .sb-search { display: none !important; }
body#layout .sb-header { position: relative; }
body#layout .sb-hero, body#layout .sb-why, body#layout .sb-stats { display: block !important; }

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .sb-hero-grid, .sb-news-box, .sb-layout { grid-template-columns: 1fr; }
  .sb-sidebar { order: 2; }
  .sb-why-grid, .sb-stats .container, .sb-foot-grid { grid-template-columns: 1fr 1fr; }
  .sb-hero-art { min-height: 320px; }
  .posts-grid, .blog-posts.hfeed,
  body:not(.is-homepage) .posts-grid,
  body:not(.is-homepage) .blog-posts.hfeed { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 780px) {
  .sb-nav, .sb-cta { display: none; }
  .sb-burger { display: grid; }
  .posts-grid, .blog-posts.hfeed,
  body:not(.is-homepage) .posts-grid,
  body:not(.is-homepage) .blog-posts.hfeed,
  .sb-related-grid { grid-template-columns: 1fr; }
  .sb-hero { padding: 36px 0 10px; }
  .sb-why-grid, .sb-stats .container, .sb-foot-grid { grid-template-columns: 1fr; }
  .sb-news-box form { flex-direction: column; }
  .sb-copy { flex-direction: column; }
}
@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
}

head.b:template-skin:



body#layout { width: 980px; margin: 20px auto; background: #fff6ec; }
body#layout .sb-preloader, body#layout .sb-drawer, body#layout .sb-search, body#layout .sb-cookie, body#layout .sb-top, body#layout .sb-wa { display:none !important; }
body#layout .sb-header { position: relative; }
body#layout .sb-hero, body#layout .sb-why, body#layout .sb-stats, body#layout .sb-news { display:block !important; }

body.script:
//
(function () {
  'use strict';

  var doc = document;
  var root = doc.documentElement;
  var body = doc.body;

  function qs(sel, ctx) { return (ctx || doc).querySelector(sel); }
  function qsa(sel, ctx) { return Array.prototype.slice.call((ctx || doc).querySelectorAll(sel)); }

  /* Preloader */
  window.addEventListener('load', function () {
    var p = qs('.sb-preloader');
    if (p) p.classList.add('hide');
  });
  setTimeout(function () {
    var p = qs('.sb-preloader');
    if (p) p.classList.add('hide');
  }, 2200);

  /* Dark mode */
  var savedTheme = localStorage.getItem('sb-theme');
  if (savedTheme) root.setAttribute('data-theme', savedTheme);
  function toggleTheme() {
    var next = root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
    root.setAttribute('data-theme', next);
    localStorage.setItem('sb-theme', next);
  }
  qsa('[data-action="theme"]').forEach(function (btn) {
    btn.addEventListener('click', toggleTheme);
  });

  /* Header scroll + progress */
  var header = qs('.sb-header');
  var bar = qs('.sb-progress');
  var topBtn = qs('.sb-top');
  function onScroll() {
    var y = window.scrollY || root.scrollTop;
    if (header) header.classList.toggle('is-scrolled', y > 8);
    if (topBtn) topBtn.classList.toggle('show', y > 500);
    if (bar) {
      var h = root.scrollHeight - window.innerHeight;
      bar.style.width = (h > 0 ? (y / h) * 100 : 0) + '%';
    }
  }
  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();

  /* Drawer */
  var drawer = qs('.sb-drawer');
  function openDrawer(open) {
    if (!drawer) return;
    drawer.classList.toggle('open', open);
    body.style.overflow = open ? 'hidden' : '';
  }
  qsa('[data-action="menu"]').forEach(function (b) {
    b.addEventListener('click', function () { openDrawer(true); });
  });
  qsa('[data-action="menu-close"]').forEach(function (b) {
    b.addEventListener('click', function () { openDrawer(false); });
  });

  /* Clone nav into drawer */
  var srcNav = qs('.sb-nav');
  var dstNav = qs('.sb-drawer-nav');
  if (srcNav && dstNav && !dstNav.childElementCount) {
    dstNav.innerHTML = srcNav.innerHTML;
  }

  /* Search overlay */
  var search = qs('.sb-search');
  function openSearch(open) {
    if (!search) return;
    search.classList.toggle('open', open);
    body.style.overflow = open ? 'hidden' : '';
    if (open) {
      var inp = qs('.sb-search input[type="text"]');
      if (inp) setTimeout(function () { inp.focus(); }, 50);
    }
  }
  qsa('[data-action="search"]').forEach(function (b) {
    b.addEventListener('click', function () { openSearch(true); });
  });
  qsa('[data-action="search-close"]').forEach(function (b) {
    b.addEventListener('click', function () { openSearch(false); });
  });
  doc.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') { openDrawer(false); openSearch(false); closeLite(); }
    if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
      e.preventDefault();
      openSearch(true);
    }
  });

  /* Back to top */
  if (topBtn) {
    topBtn.addEventListener('click', function () {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }

  /* Cookie */
  var cookie = qs('.sb-cookie');
  if (cookie) {
    if (localStorage.getItem('sb-cookie') === '1') cookie.style.display = 'none';
    var ok = qs('[data-action="cookie"]');
    if (ok) ok.addEventListener('click', function () {
      localStorage.setItem('sb-cookie', '1');
      cookie.style.display = 'none';
    });
  }

  /* Reading time on cards + article */
  function words(el) {
    return (el && (el.innerText || el.textContent) || '').trim().split(/\s+/).filter(Boolean).length;
  }
  qsa('[data-readtime]').forEach(function (el) {
    var target = qs(el.getAttribute('data-readtime')) || qs('.post-body') || el;
    var n = Math.max(1, Math.round(words(target) / 200));
    el.textContent = n + ' min read';
  });
  qsa('.post-outer').forEach(function (card) {
    var slot = qs('.js-read', card);
    var src = qs('.post-snippet', card) || qs('.post-body', card);
    if (slot && src) {
      var n = Math.max(1, Math.round(words(src) / 180));
      slot.textContent = n + ' min';
    }
  });

  /* TOC */
  var toc = qs('#sb-toc-list');
  var article = qs('.post-body');
  if (toc && article && body.classList.contains('is-post')) {
    var heads = qsa('h2, h3', article);
    if (!heads.length) {
      var box = qs('.sb-toc');
      if (box) box.style.display = 'none';
    } else {
      heads.forEach(function (h, i) {
        if (!h.id) h.id = 'h-' + (i + 1);
        var li = doc.createElement('li');
        var a = doc.createElement('a');
        a.href = '#' + h.id;
        a.textContent = h.textContent;
        if (h.tagName === 'H3') li.style.marginLeft = '14px';
        li.appendChild(a);
        toc.appendChild(li);
      });
    }
    var tog = qs('[data-action="toc"]');
    if (tog) tog.addEventListener('click', function () {
      toc.style.display = toc.style.display === 'none' ? '' : 'none';
    });
  }

  /* Copy code */
  qsa('.post-body pre').forEach(function (pre) {
    pre.style.position = 'relative';
    var btn = doc.createElement('button');
    btn.className = 'copy-btn';
    btn.type = 'button';
    btn.textContent = 'Copy';
    btn.addEventListener('click', function () {
      var txt = pre.innerText;
      if (navigator.clipboard) navigator.clipboard.writeText(txt);
      btn.textContent = 'Copied';
      setTimeout(function () { btn.textContent = 'Copy'; }, 1400);
    });
    pre.appendChild(btn);
  });

  /* Lightbox */
  var lite = qs('.sb-lite');
  var liteImg = lite ? qs('img', lite) : null;
  function closeLite() {
    if (lite) lite.classList.remove('open');
  }
  if (lite) {
    lite.addEventListener('click', closeLite);
    qsa('.post-body img').forEach(function (img) {
      img.style.cursor = 'zoom-in';
      img.addEventListener('click', function () {
        liteImg.src = img.src;
        lite.classList.add('open');
      });
    });
  }

  /* Share */
  function share(net) {
    var url = encodeURIComponent(location.href);
    var title = encodeURIComponent(doc.title);
    var map = {
      fb: 'https://www.facebook.com/sharer/sharer.php?u=' + url,
      tw: 'https://twitter.com/intent/tweet?url=' + url + '&text=' + title,
      wa: 'https://api.whatsapp.com/send?text=' + title + '%20' + url,
      li: 'https://www.linkedin.com/shareArticle?mini=true&url=' + url + '&title=' + title,
      tg: 'https://t.me/share/url?url=' + url + '&text=' + title,
      mail: 'mailto:?subject=' + title + '&body=' + url
    };
    if (net === 'copy') {
      if (navigator.clipboard) navigator.clipboard.writeText(location.href);
      return;
    }
    if (map[net]) window.open(map[net], '_blank', 'noopener,width=640,height=520');
  }
  qsa('[data-share]').forEach(function (b) {
    b.addEventListener('click', function (e) {
      e.preventDefault();
      share(b.getAttribute('data-share'));
    });
  });

  /* Related posts via Blogger JSON feed */
  var rel = qs('#sb-related');
  if (rel && body.classList.contains('is-post')) {
    var label = rel.getAttribute('data-label') || '';
    var current = rel.getAttribute('data-current') || location.href;
    var feed = '/feeds/posts/summary' + (label ? '/-/' + encodeURIComponent(label) : '') + '?alt=json&max-results=6';
    fetch(feed).then(function (r) { return r.json(); }).then(function (data) {
      var entries = (data.feed && data.feed.entry) || [];
      var html = '';
      var n = 0;
      entries.forEach(function (e) {
        var link = '';
        (e.link || []).forEach(function (l) { if (l.rel === 'alternate') link = l.href; });
        if (!link || current.indexOf(link) !== -1) return;
        if (n >= 3) return;
        n++;
        var img = 'data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="400" height="225"><rect fill="%23FECDA5" width="100%" height="100%"/></svg>';
        if (e.media$thumbnail && e.media$thumbnail.url) {
          img = e.media$thumbnail.url.replace(/s\d+-c/, 's400');
        }
        var title = e.title && e.title.$t ? e.title.$t : 'Post';
        html += '<a class="sb-rel" href="' + link + '"><img src="' + img + '" alt=""/><div>' + title + '</div></a>';
      });
      if (html) rel.innerHTML = html;
      else rel.parentNode.style.display = 'none';
    }).catch(function () {
      if (rel.parentNode) rel.parentNode.style.display = 'none';
    });
  }

  /* Stats count-up */
  var stats = qsa('.sb-stat b[data-count]');
  if (stats.length && 'IntersectionObserver' in window) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (!en.isIntersecting) return;
        var el = en.target;
        var end = parseFloat(el.getAttribute('data-count'));
        var suf = el.getAttribute('data-suf') || '';
        var t0 = performance.now();
        function tick(now) {
          var p = Math.min(1, (now - t0) / 1200);
          var val = end * (1 - Math.pow(1 - p, 3));
          el.textContent = (end % 1 ? val.toFixed(1) : Math.round(val)) + suf;
          if (p < 1) requestAnimationFrame(tick);
        }
        requestAnimationFrame(tick);
        io.unobserve(el);
      });
    }, { threshold: 0.4 });
    stats.forEach(function (s) { io.observe(s); });
  }

  /* Lazy images fallback */
  qsa('img[data-src]').forEach(function (img) {
    img.src = img.getAttribute('data-src');
  });

  /* Year */
  qsa('[data-year]').forEach(function (el) {
    el.textContent = new Date().getFullYear();
  });
})();

//
